    def binary_search(arr, target, first_occurrence):
        start = 0
        end = len(arr) - 1
        index = -1
        while start <= end:
            mid = (start + end) // 2
            if arr[mid] == target:
                index = mid
                if first_occurrence:
                    end = mid - 1  # Search in the left half
                else:
                    start = mid + 1  # Search in the right half
            elif arr[mid] < target:
                start = mid + 1
            else:
                end = mid - 1
        return index

    first_occurrence = binary_search(arr, x, True)
    last_occurrence = binary_search(arr, x, False)

    # Check if the element x appears more than n/2 times
    return (last_occurrence - first_occurrence + 1) > (n // 2)

