    Calculate the length of the longest palindromic subsequence in the given string.
    A palindromic subsequence is a sequence that appears in the same relative order,
    but not necessarily contiguous, and reads the same backward as forward.
    """
    def longest_palindromic_subsequence(s, i, j, memo):
        if i == j:
            return 1
        if i > j:
            return 0
        if (i, j) in memo:
            return memo[(i, j)]
        if s[i] == s[j]:
            memo[(i, j)] = 2 + longest_palindromic_subsequence(s, i + 1, j - 1, memo)
